-- Camp Room additive schema v1. Existing camp_room_state is not read or dropped.
-- Monetary values are integer KRW minor units; prices/addresses on orders are
-- historical facts. Computed order subtotal and total are not stored.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS cr_schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS cr_scopes(scope_id TEXT PRIMARY KEY, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS cr_profiles(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, PRIMARY KEY(scope_id,profile_id), FOREIGN KEY(scope_id) REFERENCES cr_scopes(scope_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_providers(scope_id TEXT NOT NULL, provider_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('catalog','booking','weather','commerce')), PRIMARY KEY(scope_id,provider_id), FOREIGN KEY(scope_id) REFERENCES cr_scopes(scope_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_provider_runs(scope_id TEXT NOT NULL, provider_id TEXT NOT NULL, configured INTEGER NOT NULL CHECK(configured IN(0,1)), status TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN('demo','live')), message TEXT NOT NULL, completed_at TEXT NOT NULL, expires_at TEXT NOT NULL, variant TEXT NOT NULL, PRIMARY KEY(scope_id,provider_id), FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_campsites(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, provider_id TEXT NOT NULL, name TEXT NOT NULL, region TEXT NOT NULL, address TEXT NOT NULL, latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180), nightly_price INTEGER CHECK(nightly_price>=0), currency TEXT NOT NULL DEFAULT 'KRW' CHECK(currency='KRW'), car_camping_allowed INTEGER CHECK(car_camping_allowed IN(0,1)), ev_charging_allowed INTEGER CHECK(ev_charging_allowed IN(0,1)), description TEXT NOT NULL, image_url TEXT NOT NULL, check_in_time TEXT NOT NULL, check_out_time TEXT NOT NULL, source_updated_at TEXT NOT NULL, source_mode TEXT NOT NULL CHECK(source_mode IN('demo','live')), provider_modified_at TEXT, coverage TEXT, fallback_reason TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), PRIMARY KEY(scope_id,campsite_id), FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_facilities(code TEXT PRIMARY KEY) STRICT;
CREATE TABLE IF NOT EXISTS cr_campsite_facilities(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, facility_code TEXT NOT NULL, PRIMARY KEY(scope_id,campsite_id,facility_code), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id) ON DELETE CASCADE, FOREIGN KEY(facility_code) REFERENCES cr_facilities(code)) STRICT;
CREATE TABLE IF NOT EXISTS cr_campsite_rules(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), rule_text TEXT NOT NULL, PRIMARY KEY(scope_id,campsite_id,position), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_receiving_policies(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, accepts_parcels INTEGER NOT NULL CHECK(accepts_parcels IN(0,1)), location TEXT NOT NULL, instructions TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('provider','admin')), updated_at TEXT NOT NULL, CHECK(accepts_parcels=0 OR length(trim(location))>0), PRIMARY KEY(scope_id,campsite_id), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_campsite_availability_overviews(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, provider_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('available','limited','unavailable','unknown')), remaining INTEGER CHECK(remaining>=0), coverage TEXT NOT NULL, checked_at TEXT NOT NULL, demo INTEGER NOT NULL CHECK(demo IN(0,1)), PRIMARY KEY(scope_id,campsite_id), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_trips(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, campsite_id TEXT NOT NULL, check_in TEXT NOT NULL CHECK(length(check_in)=10 AND date(check_in) IS NOT NULL AND date(check_in)=check_in), check_out TEXT NOT NULL CHECK(length(check_out)=10 AND date(check_out) IS NOT NULL AND date(check_out)=check_out), guests INTEGER NOT NULL CHECK(guests BETWEEN 1 AND 8), navigation_started INTEGER NOT NULL CHECK(navigation_started IN(0,1)), updated_at TEXT NOT NULL, CHECK(check_out>check_in AND julianday(check_out)-julianday(check_in)<=30), PRIMARY KEY(scope_id,profile_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_profiles(scope_id,profile_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_zones(zone_id TEXT PRIMARY KEY CHECK(zone_id IN('front','rear'))) STRICT;
CREATE TABLE IF NOT EXISTS cr_saved_scenes(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, scene_id TEXT NOT NULL, label TEXT NOT NULL, target_temperature REAL CHECK(target_temperature BETWEEN 16 AND 30), windows_closed INTEGER CHECK(windows_closed IN(0,1)), PRIMARY KEY(scope_id,profile_id,scene_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_profiles(scope_id,profile_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_saved_scene_zones(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, scene_id TEXT NOT NULL, zone_id TEXT NOT NULL, reading_light INTEGER NOT NULL CHECK(reading_light IN(0,1)), ambient_brightness REAL NOT NULL CHECK(ambient_brightness BETWEEN 0 AND 100), blind_level REAL NOT NULL CHECK(blind_level BETWEEN 0 AND 100), PRIMARY KEY(scope_id,profile_id,scene_id,zone_id), FOREIGN KEY(scope_id,profile_id,scene_id) REFERENCES cr_saved_scenes(scope_id,profile_id,scene_id) ON DELETE CASCADE, FOREIGN KEY(zone_id) REFERENCES cr_zones(zone_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_vehicle_states(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode='demo'), motion_state TEXT NOT NULL CHECK(motion_state IN('parked','moving','unknown')), soc REAL CHECK(soc BETWEEN 0 AND 100), cabin_temperature REAL, target_temperature REAL, doors_closed INTEGER CHECK(doors_closed IN(0,1)), windows_closed INTEGER CHECK(windows_closed IN(0,1)), last_scene_id TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(scope_id,profile_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_profiles(scope_id,profile_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,profile_id,last_scene_id) REFERENCES cr_saved_scenes(scope_id,profile_id,scene_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_vehicle_zones(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, zone_id TEXT NOT NULL, reading_light INTEGER NOT NULL CHECK(reading_light IN(0,1)), ambient_brightness REAL NOT NULL CHECK(ambient_brightness BETWEEN 0 AND 100), blind_level REAL NOT NULL CHECK(blind_level BETWEEN 0 AND 100), PRIMARY KEY(scope_id,profile_id,zone_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_vehicle_states(scope_id,profile_id) ON DELETE CASCADE, FOREIGN KEY(zone_id) REFERENCES cr_zones(zone_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_products(scope_id TEXT NOT NULL, product_id TEXT NOT NULL, name TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), currency TEXT NOT NULL CHECK(currency='KRW'), category TEXT NOT NULL, recommendation_reason TEXT NOT NULL, image_url TEXT NOT NULL, PRIMARY KEY(scope_id,product_id), FOREIGN KEY(scope_id) REFERENCES cr_scopes(scope_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_inventory(scope_id TEXT NOT NULL, product_id TEXT NOT NULL, available INTEGER NOT NULL CHECK(available>=0), PRIMARY KEY(scope_id,product_id), FOREIGN KEY(scope_id,product_id) REFERENCES cr_products(scope_id,product_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_carts(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, PRIMARY KEY(scope_id,profile_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_profiles(scope_id,profile_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_cart_items(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, product_id TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99), PRIMARY KEY(scope_id,profile_id,product_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_carts(scope_id,profile_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,product_id) REFERENCES cr_products(scope_id,product_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_orders(scope_id TEXT NOT NULL, order_id TEXT NOT NULL, profile_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status='demo_confirmed'), mode TEXT NOT NULL CHECK(mode='demo'), created_at TEXT NOT NULL, shipping_charge INTEGER NOT NULL CHECK(shipping_charge>=0), currency TEXT NOT NULL CHECK(currency='KRW'), PRIMARY KEY(scope_id,order_id), UNIQUE(scope_id,profile_id,order_id), FOREIGN KEY(scope_id,profile_id) REFERENCES cr_profiles(scope_id,profile_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_order_items(scope_id TEXT NOT NULL, order_id TEXT NOT NULL, line_number INTEGER NOT NULL CHECK(line_number>=0), product_id TEXT NOT NULL, product_name_snapshot TEXT NOT NULL, unit_price INTEGER NOT NULL CHECK(unit_price>=0), quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99), PRIMARY KEY(scope_id,order_id,line_number), UNIQUE(scope_id,order_id,product_id), FOREIGN KEY(scope_id,order_id) REFERENCES cr_orders(scope_id,order_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,product_id) REFERENCES cr_products(scope_id,product_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_order_deliveries(scope_id TEXT NOT NULL, order_id TEXT NOT NULL, destination TEXT NOT NULL CHECK(destination IN('home','campsite')), eta TEXT NOT NULL CHECK(length(eta)=10 AND date(eta) IS NOT NULL AND date(eta)=eta), recipient_name TEXT NOT NULL, address_snapshot TEXT NOT NULL, site_reference TEXT NOT NULL, phone TEXT, campsite_id TEXT, check_in TEXT CHECK(check_in IS NULL OR (length(check_in)=10 AND date(check_in) IS NOT NULL AND date(check_in)=check_in)), check_out TEXT CHECK(check_out IS NULL OR (length(check_out)=10 AND date(check_out) IS NOT NULL AND date(check_out)=check_out)), CHECK(destination='home' OR (campsite_id IS NOT NULL AND check_in IS NOT NULL AND check_out IS NOT NULL AND check_out>check_in AND julianday(check_out)-julianday(check_in)<=30 AND eta>=check_in AND eta<check_out)), PRIMARY KEY(scope_id,order_id), FOREIGN KEY(scope_id,order_id) REFERENCES cr_orders(scope_id,order_id) ON DELETE CASCADE, FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_order_receiving_conditions(scope_id TEXT NOT NULL, order_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), condition_text TEXT NOT NULL, PRIMARY KEY(scope_id,order_id,position), FOREIGN KEY(scope_id,order_id) REFERENCES cr_orders(scope_id,order_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_order_fulfillment(scope_id TEXT NOT NULL, order_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','packing','ready','cancelled')), admin_note TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(scope_id,order_id), FOREIGN KEY(scope_id,order_id) REFERENCES cr_orders(scope_id,order_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_idempotency_keys(scope_id TEXT NOT NULL, profile_id TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, order_id TEXT NOT NULL, PRIMARY KEY(scope_id,profile_id,request_key), UNIQUE(scope_id,profile_id,order_id), FOREIGN KEY(scope_id,profile_id,order_id) REFERENCES cr_orders(scope_id,profile_id,order_id) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_weather_queries(scope_id TEXT NOT NULL, query_key TEXT NOT NULL, campsite_id TEXT NOT NULL, check_in TEXT NOT NULL CHECK(length(check_in)=10 AND date(check_in) IS NOT NULL AND date(check_in)=check_in), check_out TEXT NOT NULL CHECK(length(check_out)=10 AND date(check_out) IS NOT NULL AND date(check_out)=check_out), provider_id TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT NOT NULL, variant TEXT NOT NULL, summary TEXT NOT NULL, overnight_low REAL, rain_probability REAL CHECK(rain_probability BETWEEN 0 AND 100), demo INTEGER NOT NULL CHECK(demo IN(0,1)), status TEXT NOT NULL CHECK(status IN('available','unavailable')), message TEXT, issued_at TEXT, grid_nx INTEGER, grid_ny INTEGER, CHECK(check_out>check_in AND julianday(check_out)-julianday(check_in)<=30), PRIMARY KEY(scope_id,query_key), UNIQUE(scope_id,campsite_id,check_in,check_out), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id), FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_weather_forecasts(scope_id TEXT NOT NULL, query_key TEXT NOT NULL, forecast_time TEXT NOT NULL, temperature REAL NOT NULL, condition TEXT NOT NULL, rain_probability REAL CHECK(rain_probability BETWEEN 0 AND 100), PRIMARY KEY(scope_id,query_key,forecast_time), FOREIGN KEY(scope_id,query_key) REFERENCES cr_weather_queries(scope_id,query_key) ON DELETE CASCADE) STRICT;
CREATE TABLE IF NOT EXISTS cr_refresh_leases(scope_id TEXT NOT NULL, job_key TEXT NOT NULL, lease_owner TEXT NOT NULL, expires_at TEXT NOT NULL, PRIMARY KEY(scope_id,job_key), FOREIGN KEY(scope_id) REFERENCES cr_scopes(scope_id) ON DELETE CASCADE) STRICT;
CREATE INDEX IF NOT EXISTS cr_orders_profile_created_idx ON cr_orders(scope_id,profile_id,created_at DESC);
CREATE INDEX IF NOT EXISTS cr_campsites_provider_idx ON cr_campsites(scope_id,provider_id,active);
CREATE INDEX IF NOT EXISTS cr_weather_expiry_idx ON cr_weather_queries(scope_id,expires_at);

-- Overview values are explicitly demo fixtures or unknown provider coverage;
-- they are never used as a dated live reservation inventory claim.
CREATE TABLE IF NOT EXISTS cr_availability_queries(scope_id TEXT NOT NULL, campsite_id TEXT NOT NULL, check_in TEXT NOT NULL CHECK(length(check_in)=10 AND date(check_in) IS NOT NULL AND date(check_in)=check_in), check_out TEXT NOT NULL CHECK(length(check_out)=10 AND date(check_out) IS NOT NULL AND date(check_out)=check_out), guests INTEGER NOT NULL CHECK(guests BETWEEN 1 AND 8), slot_type TEXT NOT NULL CHECK(slot_type='camping'), provider_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('available','limited','unavailable','unknown')), remaining INTEGER CHECK(remaining>=0), coverage TEXT NOT NULL, checked_at TEXT NOT NULL, expires_at TEXT NOT NULL, demo INTEGER NOT NULL CHECK(demo IN(0,1)), CHECK(check_out>check_in AND julianday(check_out)-julianday(check_in)<=30), PRIMARY KEY(scope_id,campsite_id,check_in,check_out,guests,slot_type), FOREIGN KEY(scope_id,campsite_id) REFERENCES cr_campsites(scope_id,campsite_id), FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id)) STRICT;
CREATE TABLE IF NOT EXISTS cr_refresh_runs(scope_id TEXT NOT NULL, run_id TEXT NOT NULL, job_key TEXT NOT NULL, provider_id TEXT, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL CHECK(status IN('running','succeeded','failed','skipped')), attempts INTEGER NOT NULL CHECK(attempts>=1), error_code TEXT, CHECK((status='running' AND finished_at IS NULL) OR (status<>'running' AND finished_at IS NOT NULL)), PRIMARY KEY(scope_id,run_id), FOREIGN KEY(scope_id) REFERENCES cr_scopes(scope_id), FOREIGN KEY(scope_id,provider_id) REFERENCES cr_providers(scope_id,provider_id)) STRICT;
CREATE INDEX IF NOT EXISTS cr_refresh_runs_job_idx ON cr_refresh_runs(scope_id,job_key,started_at DESC);
